import {CATEGORIES,DEFAULT_METRICS,BADGES,makeDemoState,makeBlankState,evaluate,xpLevel,grantXP,refreshBadges,recordSnapshot,bumpRules,uid,isoDay} from './engine.js';
const $=s=>document.querySelector(s);const app=$('#app');
let s=null,mode=null,email='',revision=0,page='dashboard',selectedCat='health',modal=null,authPage='welcome',onboardStep=0,editObs=null,questFilter='active',metricFilter='all',saveBusy=false,pendingSave=null,toastTimer=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,x=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[x]));
const icon=(name,cls='')=>`<svg class="icon ${cls}" aria-hidden="true"><use href="#i-${name||'sparkles'}"></use></svg>`;
const scoreText=n=>n===null||n===undefined?'—':Number(n).toFixed(1);
const catList=()=>CATEGORIES.concat(s?.customCategories||[]);
const category=id=>catList().find(c=>c.id===id)||catList()[0];
const today=()=>isoDay();
const fmtDate=d=>d?new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric',year:'numeric'}):'—';
const fmtShort=d=>new Date(d).toLocaleDateString(undefined,{month:'short',day:'numeric'});
const metricDesc=m=>`${m.target} ${m.unit} · ${m.windowDays}d window`;
const cicon=c=>`<div class="cat-icon" style="--cat-color:${c.color}">${icon(c.icon)}</div>`;
const progress=(value,color='#a797ff',h='')=>`<div class="progress ${h}" style="--bar:${color};--progress:${Math.max(0,Math.min(100,Number(value)||0))}%"><i></i></div>`;
const summary=()=>evaluate(s), level=()=>xpLevel(s.xpTransactions);
const api=async(url,method='GET',data=null)=>{const r=await fetch(url,{method,headers:data?{'Content-Type':'application/json'}:{},credentials:'same-origin',body:data?JSON.stringify(data):undefined});const out=await r.json();if(!r.ok)throw Error(out.error||'Request failed');return out;};
function toast(msg){const el=$('#toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3200);}
function save(){if(!s)return;if(mode==='demo'){try{localStorage.setItem('mortal_demo_v1',JSON.stringify(s));}catch{toast('Demo storage full. Export your data.');}return;}pendingSave=structuredClone(s);if(!saveBusy)flushSave();}
async function flushSave(){saveBusy=true;while(pendingSave){const current=pendingSave;pendingSave=null;try{const out=await api('/api/state','PUT',{state:current,revision});revision=out.revision;}catch(err){toast(`Save failed: ${err.message}`);break;}}saveBusy=false;}
function change(fn,message){fn(s);refreshBadges(s);recordSnapshot(s);save();render();if(message)toast(message);}
function switchPage(p,cat=null){page=p;if(cat)selectedCat=cat;modal=null;render();window.scrollTo({top:0,behavior:'smooth'});}
function header(title,desc='',action=''){return `<div class="page-heading"><div><div class="eyebrow">YOUR PERSONAL UNIVERSE</div><h1>${title}</h1>${desc?`<p>${desc}</p>`:''}</div>${action}</div>`;}
const nav=[['dashboard','home','Dashboard'],['categories','activity','Life categories'],['quests','swords','Quests'],['checkin','calendar','Daily check-in'],['goals','flag','My goals'],['character','user-round','Character'],['analytics','chart','Analytics'],['achievements','award','Achievements'],['settings','settings','Settings']];
function shell(inner){const l=level();const name=esc(s.profile.name||'Player');const avatar=esc((s.profile.avatar||s.profile.name?.[0]||'A').slice(0,2).toUpperCase());const active=(page==='category'?'categories':page);return `<div class="app-shell theme-glow">
 <aside class="sidebar"><div class="brand"><div class="brand-symbol" role="img" aria-label="Mortal skull emblem"></div><div><div class="brand-name">Mortal<span>.</span></div><div class="brand-sub">Your life. Your RPG.</div></div></div><div class="nav-label">MAIN MENU</div><nav class="nav-list">${nav.map(([id,ic,n])=>`<button class="nav-button ${active===id?'active':''}" data-nav="${id}">${icon(ic)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="sidebar-tip">${icon('sparkles')}<br><strong>Your story is in progress.</strong><p>Small, meaningful steps create remarkable chapters.</p></div><div class="sidebar-profile"><div class="avatar small">${avatar}</div><div style="min-width:0"><div style="font-size:12px;font-weight:730">${name}</div><div style="font-size:10px;color:#8084a4">Level ${l.level} · ${l.title}</div></div></div></aside>
 <div class="main">${mode==='demo'?'<div class="demo-banner"><b>DEMO MODE</b> · Fictional data for Alex. Changes are saved only in this browser. <button class="auth-toggle" data-action="leave-demo">Return to sign in</button></div>':''}<header class="topbar"><div class="breadcrumb">Mortal / <span>${active==='categories'&&page==='category'?esc(category(selectedCat).name):esc(nav.find(x=>x[0]===active)?.[2]||active)}</span></div><div class="top-right"><div class="date-pill">${icon('calendar')} ${new Date().toLocaleDateString(undefined,{weekday:'short',month:'short',day:'numeric'})}</div><div class="avatar top-avatar">${avatar}</div></div></header><main class="content">${inner}</main></div></div>
 <nav class="bottomnav">${[['dashboard','home','Home'],['quests','swords','Quests'],['checkin','calendar','Check-in'],['character','user-round','Player'],['settings','settings','More']].map(([p,i,n])=>`<button class="${active===p?'active':''}" data-nav="${p}">${icon(i)}<span>${n}</span></button>`).join('')}</nav>${page!=='checkin'?`<button class="floating-cta" title="Log an activity" aria-label="Log an activity" data-action="log-open">${icon('plus')}</button>`:''}`;}
function ring(res,size='big'){
 const cats=Object.values(res.categories);const n=Math.max(1,cats.length),circ=2*Math.PI*87,unit=circ/n,gap=7;let arcs='';cats.forEach((c,i)=>{const len=unit-gap,dashOffset=-i*unit;arcs+=`<circle cx="110" cy="110" r="87" fill="none" stroke="#c5baf0" stroke-opacity=".12" stroke-width="14" stroke-dasharray="${len} ${circ}" stroke-dashoffset="${dashOffset}"></circle>`;
  if(c.score!==null)arcs+=`<circle cx="110" cy="110" r="87" fill="none" stroke="${c.color}" stroke-linecap="round" stroke-width="14" stroke-dasharray="${Math.max(0,len*Math.min(1,c.score/100)-2)} ${circ}" stroke-dashoffset="${dashOffset}" opacity=".93"></circle>`;});
 return `<div class="score-visual ${size}"><svg viewBox="0 0 220 220" role="img" aria-label="Personalized Life Score ${scoreText(res.score)} out of 100"><circle cx="110" cy="110" r="68" fill="none" stroke="#ffffff" stroke-opacity=".04" stroke-width="1"/>${arcs}</svg><div class="score-center"><div class="score-big">${res.score===null?'—':Math.round(res.score)}<small>${res.score!==null?'/100':''}</small></div><div class="score-caption">LIFE SCORE</div><div class="score-status">${res.score===null?'Not assessed':res.score>=85?'Thriving':res.score>=65?'Growing well':res.score>=40?'Developing':'Getting started'}</div></div></div>`;
}
function streak(){const days=new Set(s.observations.map(o=>isoDay(o.date)));let count=0;for(let i=0;i<1000;i++){const d=new Date();d.setDate(d.getDate()-i);if(days.has(isoDay(d)))count++;else if(i>0||days.has(isoDay(new Date())))break;}return count;}
function todayCount(){const d=today();const quests=s.quests.filter(q=>q.type==='daily'&&(!q.due||q.due<=d));return [quests.filter(q=>q.doneAt).length,quests.length];}
function statCard(title,ic,value,foot,percent,color='#a798ff'){return `<div class="glass stat-card"><div class="stat-top"><span>${title}</span><span class="stat-icon">${icon(ic)}</span></div><div class="stat-value">${value}</div><div class="stat-foot">${foot}</div>${progress(percent,color)}</div>`;}
function categoryCard(c){const sc=c.score;return `<button class="category-card" data-category="${esc(c.id)}" style="--cat-color:${c.color}"><div class="rowtop">${cicon(c)}<span class="cat-score ${sc===null?'missing':''}">${scoreText(sc)}</span></div><div class="cat-name">${esc(c.name)}</div><div class="cat-desc">${esc(c.desc)}</div>${progress(sc,c.color)}<div class="cat-bottom"><span>${c.assessed}/${c.total} metrics tracked</span><span>${sc===null?'Unassessed':sc>=80?'On track':sc>=50?'In progress':'Building'}</span></div></button>`;}
function questRow(q){const c=category(q.categoryId);return `<div class="quest"><button class="quest-check ${q.doneAt?'done':''}" aria-label="${q.doneAt?'Completed':'Complete quest'}" data-complete-quest="${esc(q.id)}" ${q.doneAt?'disabled':''}>${q.doneAt?icon('check'):''}</button><div class="quest-content"><div class="quest-title ${q.doneAt?'done':''}">${esc(q.name)}</div><div class="quest-meta">${esc(c?.name||'Custom')} · ${esc(q.type||'daily')}${q.due?' · '+esc(fmtShort(q.due)):''}</div></div><div class="quest-xp">+${Number(q.reward)||0} XP</div></div>`;}
function dashboard(){const res=summary(),l=level(),[done,total]=todayCount(),name=esc(s.profile.name||'Adventurer');const quests=s.quests.filter(q=>!q.doneAt).slice(0,5),assessed=Object.values(res.categories).filter(c=>c.score!==null);const weakest=assessed.slice().sort((a,b)=>a.score-b.score)[0];
 return shell(`${header('Your life, leveled up.','A personalized overview of the things that matter to you.',`<button class="btn primary" data-action="log-open">${icon('plus')} Log activity</button>`)}
 <section class="hero"><div class="hero-body"><div class="eyebrow">✦ WELCOME BACK, PLAYER</div><h2>Every day is a<br><em>new opportunity.</em></h2><p>Keep growing at your own pace, ${name}. Your meaningful actions shape your unique character story.</p><div class="chips"><span class="chip">${icon('zap')} Level ${l.level} ${l.title}</span><span class="chip">${icon('shield')} ${res.coverage}% score coverage</span><span class="chip">${icon('activity')} ${res.confidence}% confidence</span><span class="chip">${icon('sparkles')} Version ${res.ruleVersion}</span></div></div>${ring(res)}</section>
 <div class="metrics-strip">${statCard('Player level','zap',String(l.level),`${l.current} / ${l.required} XP to next level`,l.progress)}${statCard('Lifetime XP','award',l.total.toLocaleString(),`${s.xpTransactions.length} earned rewards`,Math.min(100,l.total/25),'#f0ca85')}${statCard('Tracking streak','flame',`${streak()} days`,'Days with any recorded activity',Math.min(100,streak()*100/7),'#fcad8f')}${statCard('Daily quests','target',`${done} / ${total}`,total?'Completed scheduled daily quests':'No daily quests scheduled',total?done/total*100:0,'#75dec6')}</div>
 <div class="dash-grid"><section><div class="section-heading"><h2>Your life dimensions <span class="muted small">(${res.activeCategories})</span></h2><button class="link" data-nav="categories">Explore all ${icon('arrow-right')}</button></div><div class="category-grid">${Object.values(res.categories).map(categoryCard).join('')||'<p>No active categories yet. Enable them in Settings.</p>'}</div></section>
 <div class="right-stack"><div class="glass quest-panel"><div class="section-heading"><h2>Active quests</h2><button class="link" data-nav="quests">View all ${icon('arrow-right')}</button></div>${quests.length?quests.map(questRow).join(''):`<div class="empty">${icon('swords')}<h3>No active quests</h3><p>Create a quest to give your next step a name.</p></div>`}<button class="btn ghost" style="width:100%;margin-top:13px" data-action="quest-open">${icon('plus')} New quest</button></div>
 <div class="glass insight-panel"><div class="tip-mark">${icon('sparkles')}</div><h3>Your next chapter</h3><p>${weakest?`<strong style="color:${weakest.color}">${esc(weakest.name)}</strong> is your lowest currently assessed area (${scoreText(weakest.score)}). Review its measured inputs and decide whether its targets still fit your priorities.`:'Your categories are unassessed. Log a few measurements to begin building an evidence-based picture of your progress.'}</p><button class="link" style="border:0;background:none;color:#bcaaff;font-size:11px;cursor:pointer" data-nav="${weakest?'category':'checkin'}" ${weakest?`data-category="${weakest.id}"`:''}>${weakest?'See score breakdown':'Start a check-in'} →</button></div>
 <div class="glass insight-panel"><h3>About your score</h3><p>Your Life Score is a personal progress indicator, not a measure of human worth or medical health. Missing information is excluded, never scored zero.</p><div class="right-row"><span class="small muted">Tracking coverage</span><b>${res.coverage}%</b></div>${progress(res.coverage,'#7ee0cb')}</div></div></div>`);
}
function categories(){const res=summary();return shell(`${header('Life categories','Explore each dimension and the measurements behind it.',`<button class="btn ghost" data-nav="settings">${icon('settings')} Configure</button>`)}<div class="category-grid" style="grid-template-columns:repeat(auto-fit,minmax(230px,1fr))">${Object.values(res.categories).map(categoryCard).join('')}</div><div class="glass panel" style="margin-top:20px"><h3 class="panel-title">Your personal evaluation</h3><p class="panel-desc">Every category combines personalized progress (45%), consistency (35%), and longer-term improvement (20%) when data exists. Missing dimensions are excluded and the remainder renormalized. You can change these weights in Settings.</p><span class="data-tag">${icon('shield')} ${res.coverage}% category coverage</span></div>`);}
function metricRow(m,color='#ad9bff'){return `<div class="metric-row"><div class="metric-main"><div class="metric-head"><span>${esc(m.name)}</span><span class="metric-score" style="color:${color}">${scoreText(m.score)}</span></div><div class="metric-sub">${m.actual===null?'Awaiting data':`${esc(m.actual)} ${esc(m.unit)} recorded`} · Goal ${esc(m.target)} · ${m.observations} observation${m.observations===1?'':'s'}</div>${progress(m.score,color,'metric-progress')}</div><button class="btn ghost sm icon-only" data-log-metric="${esc(m.id)}" aria-label="Log ${esc(m.name)}">${icon('plus')}</button></div>`;}
function snapshotsFor(cat=null){return s.scoreSnapshots.filter(x=>cat?x.categories?.[cat]!=null:x.score!=null).slice(-30);}
function lineChart(points,color='#b5a0ff'){
 const actual=points.filter(p=>p.value!==null&&Number.isFinite(p.value));if(actual.length===0)return `<div class="empty">${icon('chart')}<p>No score history yet. Changes to your measurements will create time-stamped snapshots here.</p></div>`;
 const W=650,H=200,left=20,right=20,top=18,bottom=25;const x=i=>left+i*(W-left-right)/Math.max(1,actual.length-1),y=v=>top+(100-v)*(H-top-bottom)/100;
 const path=actual.map((p,i)=>`${i?'L':'M'}${x(i).toFixed(1)} ${y(p.value).toFixed(1)}`).join(' ');
 const area=`${path} L${x(actual.length-1)} ${H-bottom} L${x(0)} ${H-bottom} Z`;
 return `<div class="chart"><svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="none" role="img" aria-label="Historical scores chart"><defs><linearGradient id="chartfill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="${color}" stop-opacity=".20"/><stop offset="1" stop-color="${color}" stop-opacity="0"/></linearGradient></defs>${[0,25,50,75,100].map(t=>`<line x1="${left}" x2="${W-right}" y1="${y(t)}" y2="${y(t)}" stroke="#afacd1" stroke-opacity=".12" stroke-dasharray="3 7"/>`).join('')}<path d="${area}" fill="url(#chartfill)"/><path d="${path}" fill="none" stroke="${color}" stroke-width="3" vector-effect="non-scaling-stroke" stroke-linecap="round" stroke-linejoin="round"/>${actual.map((p,i)=>`<circle cx="${x(i)}" cy="${y(p.value)}" r="3.5" fill="${color}" stroke="#171b31" stroke-width="2"><title>${esc(fmtDate(p.date))}: ${scoreText(p.value)}</title></circle>`).join('')}</svg><div class="chart-legend"><span>${fmtShort(actual[0].date)}</span><span>0–100 personal progress scale</span><span>${fmtShort(actual.at(-1).date)}</span></div></div>`;
}
function categoryDetail(){const res=summary(),c=res.categories[selectedCat];if(!c){switchPage('categories');return '';}const defs=s.metrics.filter(m=>m.categoryId===c.id&&m.active!==false),observations=s.observations.filter(o=>defs.some(m=>m.id===o.metricId)).sort((a,b)=>new Date(b.date)-new Date(a.date)).slice(0,8),catQuests=s.quests.filter(q=>q.categoryId===c.id&&!q.doneAt);
 return shell(`${header(esc(c.name),esc(c.desc),`<button class="btn primary" data-action="log-open">${icon('plus')} Log ${esc(c.name)}</button>`)}<div class="glass detail-top"><div><span class="eyebrow">${icon(c.icon)} PERSONAL PROGRESS</span><div class="detail-score" style="color:${c.color}">${scoreText(c.score)}<span style="font-size:19px;color:#8b8ca9;letter-spacing:0"> / 100</span></div><p class="muted">${c.score===null?'Unassessed: add measurements to calculate a score.':'A personalized estimate based only on your tracked measurements.'}</p><div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:16px"><span class="data-tag">${icon('shield')} ${c.coverage}% metrics covered</span><span class="data-tag">${icon('activity')} ${c.confidence}% data confidence</span><span class="data-tag">Version ${res.ruleVersion}</span></div></div>${ring({...res,score:c.score,categories:{[c.id]:c}})}</div>
 <div class="two-columns"><div><div class="glass panel"><div class="section-heading"><h2>Measured attributes</h2><button class="link" data-nav="settings">Edit goals →</button></div>${defs.length?defs.map(m=>metricRow(res.metrics[m.id],c.color)).join(''):'<p class="faint">No attributes have been defined.</p>'}</div>
 <div class="glass panel"><div class="section-heading"><h2>Progress history</h2><span class="pill">Recorded, not projected</span></div>${lineChart(snapshotsFor(c.id).map(x=>({date:x.at,value:x.categories[c.id]})),c.color)}</div>
 <div class="glass panel"><div class="section-heading"><h2>Recent measurements</h2><button class="link" data-action="log-open">Add new ${icon('plus')}</button></div>${observations.length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Metric</th><th>Value</th><th>Date</th><th>Actions</th></tr></thead><tbody>${observations.map(o=>{const m=s.metrics.find(x=>x.id===o.metricId);return `<tr><td>${esc(m?.name)}</td><td>${esc(o.value)} ${esc(m?.unit)}</td><td>${fmtShort(o.date)}</td><td><button class="btn ghost sm" data-edit-observation="${esc(o.id)}">${icon('edit')}</button> <button class="btn ghost sm" data-delete-observation="${esc(o.id)}">${icon('trash')}</button></td></tr>`;}).join('')}</tbody></table></div>`:'<p class="faint small">No measurements recorded yet.</p>'}</div></div>
 <div><div class="glass panel"><h3 class="panel-title">Why this score?</h3><p class="panel-desc">Calculated directly from individual measurements and weights.</p>${Object.entries(c.dimensions).map(([d,v])=>`<div class="category-block"><div><div style="font-size:12px;text-transform:capitalize;font-weight:730">${esc(d)}</div><div class="small muted">${(s.dimensions[d]*100).toFixed(0)}% base weight · ${v.metricIds.length} eligible metrics</div></div><b>${scoreText(v.score)}</b></div>`).join('')||'<p class="small muted">No assessable dimensions yet.</p>'}<p class="small muted" style="margin-top:17px">Unavailable dimensions are excluded and eligible weights renormalized. Individual metric scores are capped at 100; each metric has its own method and target.</p></div>
 <div class="glass panel"><h3 class="panel-title">Scoring rules</h3>${defs.map(m=>{const v=res.metrics[m.id];return `<div style="padding:10px 0;border-bottom:1px solid var(--line)"><div class="right-row"><b style="font-size:11px">${esc(m.name)}</b><span class="pill">×${m.weight}</span></div><p style="font-size:10px;color:#868cac;line-height:1.65;margin:6px 0">${esc(v.explanation)} ${v.exemptedDays?'Exempted days: '+v.exemptedDays+'. ':''} Source: ${esc(m.source)}. ${v.lastUpdated?'Updated '+fmtShort(v.lastUpdated):'Not recorded'}.</p></div>`}).join('')}</div>
 <div class="glass panel"><div class="section-heading"><h2>Category quests</h2><button class="link" data-action="quest-open">Add ${icon('plus')}</button></div>${catQuests.length?catQuests.slice(0,5).map(questRow).join(''):'<p class="small muted">No open quests in this category.</p>'}</div></div></div>`);
}
function questsPage(){const types=['active','daily','weekly','long-term','boss','done'];const list=s.quests.filter(q=>questFilter==='active'?!q.doneAt:questFilter==='done'?!!q.doneAt:q.type===questFilter).sort((a,b)=>Number(!!a.doneAt)-Number(!!b.doneAt));const l=level();
 return shell(`${header('Your quests','Turn your intentions into achievable real-life missions.',`<button class="btn primary" data-action="quest-open">${icon('plus')} Create quest</button>`)}
 <div class="metrics-strip" style="grid-template-columns:repeat(3,1fr);margin:0 0 23px">${statCard('Quests completed','check',s.quests.filter(q=>q.doneAt).length,'Lifetime achievements',Math.min(100,s.quests.filter(q=>q.doneAt).length*5),'#75dec6')}${statCard('Available quests','swords',s.quests.filter(q=>!q.doneAt).length,'Your next adventures',Math.min(100,s.quests.filter(q=>!q.doneAt).length*10))}${statCard('Total earned XP','zap',l.total,'Across all activity',l.progress,'#f1c680')}</div>
 <div class="glass panel"><div class="right-row" style="flex-wrap:wrap;margin-bottom:18px"><h2 class="panel-title">Quest board</h2><div style="display:flex;gap:5px;flex-wrap:wrap">${types.map(t=>`<button class="btn sm ${questFilter===t?'primary':'ghost'}" data-quest-filter="${t}">${t==='long-term'?'Long-term':t[0].toUpperCase()+t.slice(1)}</button>`).join('')}</div></div>${list.length?list.map(q=>`<div class="quest" style="padding:19px 0">${questRowInner(q)}<button class="btn ghost sm" data-delete-quest="${esc(q.id)}" title="Delete quest">${icon('trash')}</button></div>`).join(''):`<div class="empty">${icon('swords')}<h3>No quests in this view</h3><p>Create a quest based on a meaningful goal. You set the pace and reward.</p><button class="btn primary" data-action="quest-open">Create a quest</button></div>`}</div>`);
}
function questRowInner(q){const c=category(q.categoryId);return `<button class="quest-check ${q.doneAt?'done':''}" aria-label="Complete quest" data-complete-quest="${esc(q.id)}" ${q.doneAt?'disabled':''}>${q.doneAt?icon('check'):''}</button><div class="quest-content"><div class="quest-title ${q.doneAt?'done':''}">${esc(q.name)}</div>${q.description?`<div class="small muted" style="margin-top:6px">${esc(q.description)}</div>`:''}<div class="quest-meta">${esc(c?.name)} · ${esc(q.type)} · ${esc(q.difficulty||'Normal')}${q.due?' · Due '+fmtDate(q.due):''}${q.doneAt?' · Completed '+fmtDate(q.doneAt):''}</div></div><div class="quest-xp">${q.doneAt?'Earned ':'+'}${Number(q.reward)} XP</div>`;}
function checkin(){const active=s.metrics.filter(m=>s.activeCategories.includes(m.categoryId)&&m.active!==false),groups=catList().filter(c=>s.activeCategories.includes(c.id));return shell(`${header('Daily check-in','Record what matters. One minute of reflection is enough.',`<button class="btn ghost" data-nav="analytics">${icon('chart')} See history</button>`)}
 <div class="glass panel"><div class="right-row"><div><h2 class="panel-title">Quick log</h2><p class="panel-desc" style="margin:4px 0 16px">Choose a metric and record an actual value. Only tracked categories appear.</p></div><span class="pill green">${esc(s.profile.intensity||'balanced')} mode</span></div>
 <form id="checkin-form" class="form-grid"><div class="field"><label for="ci-metric">Metric</label><select id="ci-metric" name="metricId" required>${active.map(m=>`<option value="${esc(m.id)}">${esc(category(m.categoryId).name)} · ${esc(m.name)}</option>`).join('')}</select></div><div class="field"><label for="ci-value">Actual value</label><input class="input" id="ci-value" name="value" type="number" min="0" step="any" required placeholder="Enter measurement"></div><div class="field"><label for="ci-date">Date</label><input class="input" id="ci-date" type="date" name="date" max="${today()}" value="${today()}" required></div><div class="field"><label for="ci-note">Note (optional)</label><input class="input" id="ci-note" name="note" maxlength="300" placeholder="What happened?"></div><div class="field full"><button class="btn primary" type="submit">${icon('check')} Save measurement and recalculate</button></div></form></div>
 <div class="glass panel"><div class="section-heading"><h2>More ways to check in</h2><span class="muted small">${active.length} configurable metrics</span></div><div class="category-grid">${groups.map(c=>`<div class="category-card" style="--cat-color:${c.color};cursor:default"><div class="right-row">${cicon(c)}<b class="small">${esc(c.name)}</b></div><div class="cat-desc" style="margin:10px 0">${s.metrics.filter(m=>m.categoryId===c.id&&m.active!==false).length} available attributes</div><button class="btn ghost sm" data-category="${esc(c.id)}">Open & log ${icon('arrow-right')}</button></div>`).join('')}</div></div>
 <div class="glass panel"><div class="section-heading"><h2>Today's entries</h2><span class="pill">${today()}</span></div>${s.observations.filter(o=>isoDay(o.date)===today()).length?`<div class="table-scroll"><table class="data-table"><thead><tr><th>Metric</th><th>Value</th><th>Note</th><th></th></tr></thead><tbody>${s.observations.filter(o=>isoDay(o.date)===today()).slice().reverse().map(o=>`<tr><td>${esc(s.metrics.find(m=>m.id===o.metricId)?.name)}</td><td>${esc(o.value)}</td><td>${esc(o.note||'—')}</td><td><button class="btn ghost sm" data-edit-observation="${esc(o.id)}">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>`:'<p class="small muted">Nothing recorded today. Your personal metrics are unassessed until you enter data.</p>'}</div>`);}
function goalsPage(){return shell(`${header('Goals & milestones','Give your ambitions structure, without setting someone else’s definition of success.',`<button class="btn primary" data-action="goal-open">${icon('plus')} New goal</button>`)}<div class="category-grid" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${s.goals.map(g=>{const c=category(g.categoryId);return `<div class="glass goal-card"><div class="right-row">${cicon(c)}<span class="pill">${esc(c.name)}</span></div><h3 style="font-size:16px;letter-spacing:-.2px;margin:0;min-height:44px">${esc(g.name)}</h3><div class="right-row"><span class="goal-value" style="color:${c.color}">${Number(g.progress)}%</span><span class="small muted">${g.targetDate?'Target '+fmtDate(g.targetDate):'No due date'}</span></div>${progress(g.progress,c.color)}<div class="right-row"><button class="btn ghost sm" data-edit-goal="${esc(g.id)}">${icon('edit')} Update progress</button><button class="btn ghost sm" data-delete-goal="${esc(g.id)}" aria-label="Delete goal">${icon('trash')}</button></div></div>`}).join('')}</div>${s.goals.length?'':'<div class="glass empty">'+icon('flag')+'<h3>Your next milestone starts here</h3><p>Create a goal that genuinely matters to you. Keep it as big or small as you need.</p><button class="btn primary" data-action="goal-open">Add a goal</button></div>'}`);}
function attributeScores(res){const refs={Vitality:['health','sleep'],Strength:['fitness'],Endurance:['fitness','health'],Focus:['career','discipline'],Knowledge:['learning'],Discipline:['discipline'],Creativity:['goals','learning'],Connection:['social'],Resilience:['finance'],Adaptability:['goals','mental']};return Object.entries(refs).map(([name,ids])=>{const scores=ids.map(id=>res.categories[id]?.score).filter(x=>x!==null&&x!==undefined);return {name,score:scores.length?Math.round(scores.reduce((a,b)=>a+b,0)/scores.length):null};});}
function radar(attrs){const cx=150,cy=145,r=108,n=attrs.length;const pt=(i,k)=>{const a=-Math.PI/2+2*Math.PI*i/n;return `${(cx+Math.cos(a)*r*k).toFixed(1)},${(cy+Math.sin(a)*r*k).toFixed(1)}`};return `<svg viewBox="0 0 300 290" style="width:100%;max-width:360px;display:block;margin:auto" role="img" aria-label="Personalized RPG attributes radar chart">${[.25,.5,.75,1].map(k=>`<polygon points="${attrs.map((_,i)=>pt(i,k)).join(' ')}" fill="none" stroke="#a697cf" stroke-opacity=".19"/>`).join('')}${attrs.map((_,i)=>`<line x1="${cx}" y1="${cy}" x2="${pt(i,1).replace(',','" y2="')}" stroke="#a697cf" stroke-opacity=".15"/>`).join('')}<polygon points="${attrs.map((a,i)=>pt(i,(a.score||0)/100)).join(' ')}" fill="#a18cff" fill-opacity=".22" stroke="#b29eff" stroke-width="2"/>${attrs.map((a,i)=>{const [x,y]=pt(i,1.18).split(',');return `<text x="${x}" y="${y}" fill="#a9acc7" font-size="8" text-anchor="middle" dominant-baseline="middle">${esc(a.name)}</text>`}).join('')}</svg>`;}
function characterPage(){const l=level(),res=summary(),attrs=attributeScores(res),badges=BADGES.filter(b=>s.achievements.some(a=>a.id===b.id));return shell(`${header('Character profile','Your story is written through actions, not perfection.',`<button class="btn ghost" data-nav="achievements">${icon('award')} Badges</button>`)}
 <div class="glass panel"><div class="character-head"><div class="avatar character-avatar">${esc((s.profile.avatar||s.profile.name?.[0]||'A').slice(0,2).toUpperCase())}</div><div style="flex:1"><div class="eyebrow">LEVEL ${l.level} · ${l.title.toUpperCase()}</div><h2 style="font-size:30px;margin:6px 0;letter-spacing:-1px">${esc(s.profile.name||'Adventurer')}</h2><div class="small muted">${esc(s.profile.role||'Your own path')} · ${l.total.toLocaleString()} lifetime XP</div><div style="max-width:430px;margin-top:17px">${progress(l.progress,'#c1a5ff')}<div class="right-row small muted" style="margin-top:7px"><span>${l.current} / ${l.required} XP</span><span>Level ${l.level+1}</span></div></div></div></div></div>
 <div class="two-columns" style="margin-top:18px"><div class="glass panel"><h2 class="panel-title">Character attributes</h2><p class="panel-desc">Derived transparently from the matching life categories, not from XP alone.</p>${radar(attrs)}${attrs.map(a=>`<div class="attribute-row"><span>${esc(a.name)}</span>${progress(a.score,'#a998ff')}<b style="text-align:right">${a.score??'—'}</b></div>`).join('')}</div><div><div class="glass panel"><h2 class="panel-title">Unlocked achievements</h2><p class="panel-desc">${badges.length} of ${BADGES.length} milestones achieved</p>${badges.length?badges.map(b=>`<div class="category-block"><div style="display:flex;align-items:center;gap:11px"><div class="cat-icon" style="--cat-color:#c3adff">${icon(b.icon in {}?'award':'award')}</div><div><b style="font-size:12px">${esc(b.name)}</b><div class="small muted">${esc(b.description)}</div></div></div>${icon('check')}</div>`).join(''):'<p class="small muted">Your first action unlocks your first badge.</p>'}<button class="btn ghost sm" style="margin-top:16px" data-nav="achievements">See all achievements ${icon('arrow-right')}</button></div><div class="glass panel"><h2 class="panel-title">Character history</h2><p class="panel-desc">Your latest noteworthy activities</p>${s.xpTransactions.slice(-7).reverse().map(t=>`<div class="category-block"><div><b style="font-size:11px">${esc(t.reason)}</b><div class="small muted">${fmtDate(t.at)}</div></div><span class="pill gold">+${t.amount} XP</span></div>`).join('')||'<p class="small muted">Start a quest or log an activity to begin your history.</p>'}</div></div></div>`);}
function achievementsPage(){return shell(`${header('Achievements','These milestones recognize real effort over time.',`<span class="pill green">${s.achievements.length} unlocked</span>`)}<div class="badge-grid">${BADGES.map(b=>{const u=s.achievements.find(a=>a.id===b.id);return `<div class="badge-card ${u?'':'locked'}"><div class="badge-mark">${icon('award')}</div><h3>${esc(b.name)}</h3><p>${esc(b.description)}</p><div style="margin-top:10px">${u?`<span class="pill green">Unlocked ${fmtShort(u.at)}</span>`:'<span class="pill">Locked</span>'}</div></div>`}).join('')}</div><div class="glass panel" style="margin-top:20px"><h2 class="panel-title">A healthier kind of progress</h2><p class="panel-desc">Achievements commemorate milestones. There are no penalties for rest days, changing plans, or having different priorities than other players.</p></div>`);}
function analyticsPage(){const res=summary(),snaps=snapshotsFor(),scored=Object.values(res.categories).filter(c=>c.score!==null).sort((a,b)=>b.score-a.score),l=level();const weekAgo=Date.now()-7*86400000,weekXP=s.xpTransactions.filter(t=>new Date(t.at).getTime()>=weekAgo).reduce((a,t)=>a+t.amount,0),weekQuests=s.quests.filter(q=>q.doneAt&&new Date(q.doneAt).getTime()>=weekAgo).length;
 const earliest=snaps.length>1?snaps[0].score:null,delta=earliest===null||res.score===null?null:Math.round((res.score-earliest)*10)/10;
 return shell(`${header('Life analytics','Progress that is personal, transparent, and grounded in your own data.',`<button class="btn ghost" data-action="export">${icon('download')} Export data</button>`)}
 <div class="report-highlights"><div class="highlight"><b>${scoreText(res.score)}</b><span>Current Life Score</span></div><div class="highlight"><b>${delta===null?'—':(delta>0?'+':'')+delta}</b><span>Change since first snapshot</span></div><div class="highlight"><b>${res.coverage}%</b><span>Assessed category coverage</span></div></div>
 <div class="glass panel" style="margin-top:18px"><div class="section-heading"><h2>Life Score history</h2><span class="pill">Rule version ${res.ruleVersion}</span></div>${lineChart(snaps.map(x=>({date:x.at,value:x.score})))}<p class="small muted">Historical points retain their evaluation versions. Comparisons across changed scoring rules should be interpreted cautiously.</p></div>
 <div class="two-columns" style="margin-top:18px"><div class="glass panel"><h2 class="panel-title">Life dimension comparison</h2><p class="panel-desc">Scores from your currently eligible measurements</p>${scored.length?scored.map(c=>`<div class="category-block" style="display:block"><div class="right-row"><span class="small">${esc(c.name)}</span><b style="color:${c.color}">${scoreText(c.score)}</b></div>${progress(c.score,c.color)}</div>`).join(''):'<p class="small muted">Not enough data for category comparisons yet.</p>'}</div><div><div class="glass panel"><h2 class="panel-title">Your weekly Life Report</h2><p class="panel-desc">Based only on activity recorded in the last 7 days</p><div class="category-block"><span class="small muted">XP earned</span><b>${weekXP}</b></div><div class="category-block"><span class="small muted">Quests completed</span><b>${weekQuests}</b></div><div class="category-block"><span class="small muted">Measurements added</span><b>${s.observations.filter(o=>new Date(o.date).getTime()>=weekAgo).length}</b></div><div class="category-block"><span class="small muted">Strongest assessed area</span><b class="small">${esc(scored[0]?.name||'—')}</b></div><div style="background:#ab9cff13;border:1px solid #b2a0ff29;padding:13px;border-radius:10px;margin-top:15px;color:#aba9c4;font-size:11px;line-height:1.8">${scored.length?`Consider how your priorities relate to <strong style="color:#ddd3ff">${esc(scored.at(-1).name)}</strong>. Personal targets can always be edited.`:'Try tracking one or two small priorities this week. You do not need to assess everything at once.'}</div></div><div class="glass panel"><h2 class="panel-title">How to interpret insights</h2><p class="panel-desc">No predictive claims are made without sufficient trend data. Correlations, when available, do not establish causation. This is a personal progress tool, not a medical or financial risk assessment.</p></div></div></div>`);
}
function settingsPage(){const res=summary();const cats=catList();return shell(`${header('Settings & personalization','Make Mortal yours. Every target, category and weight is adjustable.',`<button class="btn ghost" data-action="export">${icon('download')} Export JSON</button>`)}
 <div class="settings-grid"><div class="glass panel"><h2 class="panel-title">Player profile</h2><p class="panel-desc">Only share information you want to use.</p><form id="profile-form" class="form-grid"><div class="field"><label>Name</label><input class="input" name="name" maxlength="60" value="${esc(s.profile.name)}" required></div><div class="field"><label>Character initials</label><input class="input" name="avatar" maxlength="2" value="${esc(s.profile.avatar)}"></div><div class="field full"><label>Life stage / role (optional)</label><input class="input" name="role" maxlength="80" value="${esc(s.profile.role||'')}"></div><div class="field"><label>Tracking intensity</label><select name="intensity">${['casual','balanced','detailed'].map(t=>`<option ${s.profile.intensity===t?'selected':''} value="${t}">${t[0].toUpperCase()+t.slice(1)}</option>`).join('')}</select></div><div class="field"><label>Preferred currency</label><input class="input" name="currency" maxlength="5" value="${esc(s.profile.currency||'USD')}"></div><div class="field full"><button class="btn primary" type="submit">Save profile</button></div></form></div>
 <div class="glass panel"><h2 class="panel-title">Overall scoring dimensions</h2><p class="panel-desc">Adjust the starting 45/35/20 blend. Eligible dimensions will always be renormalized.</p><form id="dimension-form"><div class="form-grid">${['progress','consistency','growth'].map(d=>`<div class="field full"><label style="text-transform:capitalize">${d} weight</label><input class="input" name="${d}" type="number" min="0" max="100" step="1" value="${Math.round(s.dimensions[d]*100)}"></div>`).join('')}</div><button class="btn primary" style="margin-top:17px" type="submit">Apply scoring dimensions</button></form><p class="small muted" style="margin-top:18px">Formula changes are versioned and saved in your personal evaluation history.</p></div>
 <div class="glass panel full"><div class="section-heading"><div><h2>Categories & importance</h2><p class="small muted">Disabled categories do not count against the Life Score.</p></div><button class="btn ghost sm" data-action="custom-category">${icon('plus')} Custom category</button></div>${cats.map(c=>`<div class="settings-row"><div style="display:flex;align-items:center;gap:10px"><input type="checkbox" aria-label="Track ${esc(c.name)}" data-category-toggle="${esc(c.id)}" ${s.activeCategories.includes(c.id)?'checked':''}>${cicon(c)}<span style="font-size:12px;font-weight:700">${esc(c.name)}</span></div><input type="range" min="0" max="5" step=".25" value="${Number(s.categoryWeights[c.id]??1)}" aria-label="${esc(c.name)} weight" data-category-weight="${esc(c.id)}"><b class="weight-value" id="weight-${esc(c.id)}" style="text-align:right;font-size:12px">×${Number(s.categoryWeights[c.id]??1)}</b></div>`).join('')}<p class="small muted" style="margin:15px 0 0">Overall assessed weight coverage: ${res.coverage}%. Weights apply only to active, assessed categories.</p></div>
 <div class="glass panel full"><div class="section-heading"><div><h2>Metric rule editor</h2><p class="small muted">Change targets, baseline values, time windows and metric weights.</p></div><button class="btn ghost sm" data-action="custom-metric">${icon('plus')} New metric</button></div><div style="max-height:510px;overflow:auto">${s.metrics.filter(m=>s.activeCategories.includes(m.categoryId)).map(m=>`<div class="category-block"><div style="min-width:0;flex:1"><b style="font-size:11px">${esc(m.name)}</b><div class="small muted">${esc(category(m.categoryId).name)} · ${esc(m.method)} · ${esc(m.dimension)} · ${m.windowDays} days</div></div><span class="pill">${esc(m.target)} ${esc(m.unit)}</span><button class="btn ghost sm" data-edit-metric="${esc(m.id)}">${icon('edit')} Edit</button></div>`).join('')}</div></div>
 <div class="glass panel"><h2 class="panel-title">Data & privacy</h2><p class="panel-desc">Your data stays private to this local server account. Demo data is browser-local and separate from real accounts.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn ghost sm" data-action="export">${icon('download')} Export</button><button class="btn ghost sm" data-action="import">Import JSON</button><button class="btn danger sm" data-action="clear-data">${icon('trash')} Clear my activity</button></div><input type="file" id="import-file" accept="application/json,.json" style="display:none"><div style="margin-top:18px"><button class="btn ghost sm" data-action="logout">${mode==='demo'?'Leave demo':'Sign out'}</button>${mode==='account'?'<button class="btn danger sm" data-action="delete-account" style="margin-left:8px">Delete account</button>':''}</div></div>
 <div class="glass panel"><h2 class="panel-title">Evaluation version history</h2><p class="panel-desc">Rule changes remain auditable.</p><div style="max-height:250px;overflow:auto">${(s.ruleHistory||[]).slice().reverse().map(r=>`<div class="category-block"><div><b style="font-size:11px">Version ${r.version}</b><div class="small muted">${esc(r.note)}</div></div><span class="small muted">${fmtShort(r.at)}</span></div>`).join('')}</div></div></div>`);}
function modalMarkup(){if(!modal)return '';
 const close=`<button class="modal-close" data-action="close-modal" aria-label="Close">${icon('x')}</button>`;
 const formHead=(title,desc)=>`<div class="right-row"> <div class="eyebrow">MORTAL CONTROL CENTER</div>${close}</div><h2>${title}</h2><p>${desc}</p>`;
 let html='';
 if(modal.type==='observation'){
  const o=modal.id?s.observations.find(o=>o.id===modal.id):null,active=s.metrics.filter(m=>s.activeCategories.includes(m.categoryId)&&m.active!==false),pref=modal.metricId||o?.metricId||active.find(m=>m.categoryId===selectedCat)?.id||active[0]?.id;
  html=`${formHead(o?'Edit measurement':'Log an activity','Your score recalculates from real values and configured targets.')}<form id="observation-form" class="form-grid"><input type="hidden" name="id" value="${esc(o?.id||'')}"><div class="field full"><label>Tracked metric</label><select name="metricId" required>${active.map(m=>`<option value="${esc(m.id)}" ${pref===m.id?'selected':''}>${esc(category(m.categoryId).name)} · ${esc(m.name)} (${esc(m.unit)})</option>`).join('')}</select></div><div class="field"><label>Actual value</label><input class="input" type="number" name="value" min="0" step="any" value="${esc(o?.value??'')}" required></div><div class="field"><label>Recorded date</label><input class="input" type="date" name="date" max="${today()}" value="${esc(o?.date?isoDay(o.date):today())}" required></div><div class="field full"><label>Optional note</label><textarea name="note" maxlength="300" placeholder="Your thoughts about this entry">${esc(o?.note||'')}</textarea></div><div class="field full"><div class="pill">${icon('info')} New entries earn a small XP reward once per metric each day; edits do not.</div></div><div class="field full"><button class="btn primary" type="submit">${icon('check')} ${o?'Update measurement':'Save activity'}</button></div></form>`;
 }
 if(modal.type==='quest')html=`${formHead('Create a quest','Turn one meaningful action into a personal mission.')}<form id="quest-form" class="form-grid"><div class="field full"><label>Quest name</label><input class="input" name="name" maxlength="100" placeholder="e.g. Take a refreshing walk" required></div><div class="field full"><label>Description (optional)</label><textarea name="description" maxlength="400" placeholder="What does success look like?"></textarea></div><div class="field"><label>Category</label><select name="categoryId">${s.activeCategories.map(id=>`<option ${id===selectedCat?'selected':''} value="${esc(id)}">${esc(category(id).name)}</option>`).join('')}</select></div><div class="field"><label>Type</label><select name="type"><option value="daily">Daily</option><option value="weekly">Weekly</option><option value="long-term">Long-term</option><option value="boss">Boss quest</option></select></div><div class="field"><label>Difficulty</label><select name="difficulty"><option>Easy</option><option selected>Normal</option><option>Challenging</option><option>Major milestone</option></select></div><div class="field"><label>Due date (optional)</label><input class="input" name="due" type="date"></div><div class="field full"><label>XP reward (5–1000)</label><input class="input" name="reward" type="number" min="5" max="1000" value="25" required></div><div class="field full"><button class="btn primary" type="submit">${icon('plus')} Add quest</button></div></form>`;
 if(modal.type==='goal'){
  const g=s.goals.find(x=>x.id===modal.id);html=`${formHead(g?'Update a goal':'Create a goal','You decide what an accomplished milestone means.')}<form id="goal-form" class="form-grid"><input type="hidden" name="id" value="${esc(g?.id||'')}"><div class="field full"><label>Goal</label><input class="input" maxlength="120" name="name" value="${esc(g?.name||'')}" placeholder="What matters to you?" required></div><div class="field"><label>Category</label><select name="categoryId">${s.activeCategories.map(id=>`<option value="${esc(id)}" ${id===g?.categoryId?'selected':''}>${esc(category(id).name)}</option>`).join('')}</select></div><div class="field"><label>Target date (optional)</label><input class="input" name="targetDate" type="date" value="${esc(g?.targetDate||'')}"></div><div class="field full"><label>Milestone progress (%)</label><input class="input" name="progress" type="number" min="0" max="100" step="1" value="${g?.progress??0}" required></div><div class="field full"><button type="submit" class="btn primary">${icon('check')} Save goal</button></div></form>`;
 }
 if(modal.type==='metric'){
  const m=s.metrics.find(x=>x.id===modal.id);html=`${formHead(m?'Edit scoring rule':'Create custom metric','Structured calculations keep scores explainable and safe.')}<form id="metric-form" class="form-grid"><input type="hidden" name="id" value="${esc(m?.id||'')}"><div class="field full"><label>Metric name</label><input class="input" name="name" maxlength="70" value="${esc(m?.name||'')}" required></div><div class="field"><label>Category</label><select name="categoryId">${catList().map(c=>`<option value="${esc(c.id)}" ${m?.categoryId===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></div><div class="field"><label>Unit</label><input class="input" name="unit" maxlength="35" value="${esc(m?.unit||'sessions')}" required></div><div class="field"><label>Method</label><select name="method">${['higher','lower','range','progress','consistency','completion','self'].map(t=>`<option value="${t}" ${m?.method===t?'selected':''}>${t}</option>`).join('')}</select></div><div class="field"><label>Dimension</label><select name="dimension">${['progress','consistency','growth'].map(d=>`<option ${m?.dimension===d?'selected':''} value="${d}">${d}</option>`).join('')}</select></div><div class="field"><label>Personal target</label><input class="input" name="target" type="number" step="any" value="${m?.target??5}" required></div><div class="field"><label>Baseline</label><input class="input" name="baseline" type="number" step="any" value="${m?.baseline??0}" required></div><div class="field"><label>Low end (range)</label><input class="input" name="min" type="number" step="any" value="${m?.min??0}"></div><div class="field"><label>High end (range)</label><input class="input" name="max" type="number" step="any" value="${m?.max??100}"></div><div class="field"><label>Evaluation window, days</label><input class="input" name="windowDays" type="number" min="1" max="3650" value="${m?.windowDays??7}" required></div><div class="field"><label>Metric weight</label><input class="input" name="weight" type="number" min="0" max="100" step="0.1" value="${m?.weight??1}" required></div><div class="field"><label>Aggregation</label><select name="aggregate">${['sum','latest','average','max'].map(a=>`<option ${m?.aggregate===a?'selected':''} value="${a}">${a}</option>`).join('')}</select></div><div class="field full"><label>Exclude eligible dates (comma-separated YYYY-MM-DD, optional)</label><input class="input" name="exemptDates" placeholder="2026-10-20, 2026-10-21" value="${esc((m?.exemptDates||[]).join(', '))}"></div><div class="field"><label>Pause assessment until (optional)</label><input class="input" type="date" name="pausedUntil" value="${esc(m?.pausedUntil||'')}"></div><div class="field"><label>Enabled</label><select name="active"><option value="yes" ${m?.active!==false?'selected':''}>Yes</option><option value="no" ${m?.active===false?'selected':''}>No</option></select></div><div class="field full"><button class="btn primary" type="submit">${icon('check')} Save scoring rule</button></div></form>`;
 }
 if(modal.type==='category')html=`${formHead('New life category','Build your own definition of growth, then add custom metrics.')}<form id="category-form" class="form-grid"><div class="field full"><label>Category name</label><input class="input" name="name" maxlength="45" placeholder="e.g. Music" required></div><div class="field full"><label>Description</label><input class="input" name="desc" maxlength="110" placeholder="What do you want to grow?"></div><div class="field"><label>Accent color</label><input class="input" name="color" type="color" value="#c3a6ff" style="height:48px"></div><div class="field"><label>Importance (0–5)</label><input class="input" name="weight" type="number" min="0" max="5" step=".25" value="1"></div><div class="field full"><button class="btn primary" type="submit">${icon('plus')} Create category</button></div></form>`;
 if(modal.type==='delete-account')html=`${formHead('Delete account','This permanently deletes your account and all stored measurements, goals and progress. This cannot be undone.')}<form id="delete-account-form"><div class="field"><label>Confirm with your password</label><input class="input" type="password" name="password" required></div><div class="form-actions"><button class="btn danger" type="submit">Permanently delete my account</button></div></form>`;
 return `<div class="modal-backdrop" id="modal-backdrop"><div class="modal" role="dialog" aria-modal="true" aria-label="${esc(modal.type)} dialog">${html}</div></div>`;
}
function onboarding(){const steps=['Player identity','Choose your dimensions','Define your direction'];const p=s.profile;const cats=catList();let content='';
 if(onboardStep===0)content=`<form id="onboard-step-0" class="form-grid"><div class="field"><label>What should we call you?</label><input class="input" name="name" value="${esc(p.name||'')}" required maxlength="60" placeholder="Preferred name"></div><div class="field"><label>Character initials</label><input class="input" name="avatar" value="${esc(p.avatar||'A')}" maxlength="2" placeholder="A"></div><div class="field full"><label>Your current role (optional)</label><select name="role"><option value="">Choose or skip</option>${['Student','Employee','Entrepreneur','Freelancer','Caregiver','Retired','Other'].map(x=>`<option ${p.role===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Currency</label><input class="input" name="currency" maxlength="5" value="${esc(p.currency||'USD')}"></div><div class="field"><label>Tracking intensity</label><select name="intensity">${['casual','balanced','detailed'].map(v=>`<option value="${v}" ${p.intensity===v?'selected':''}>${v[0].toUpperCase()+v.slice(1)}</option>`).join('')}</select></div><div class="field full"><button class="btn primary" type="submit">Continue ${icon('arrow-right')}</button></div></form>`;
 if(onboardStep===1)content=`<form id="onboard-step-1"><p class="panel-desc">Which dimensions matter in this chapter? You can always add or remove them.</p><div class="choose-grid">${cats.map(c=>`<label class="choose-item"><input type="checkbox" name="category" value="${c.id}" ${s.activeCategories.includes(c.id)?'checked':''}>${cicon(c)} <span>${esc(c.name)}</span></label>`).join('')}</div><div class="form-actions"><button class="btn ghost" data-action="onboard-back" type="button">Back</button><button class="btn primary" type="submit">Continue ${icon('arrow-right')}</button></div></form>`;
 if(onboardStep===2)content=`<form id="onboard-step-2" class="form-grid"><div class="field full"><label>Your top three priorities (separated by commas)</label><textarea name="priorities" placeholder="e.g. Better rest, financial organization, skill building">${esc((p.priorities||[]).join(', '))}</textarea></div><div class="field full"><label>Choose what suits you now</label><p class="small muted">Mortal starts all your categories as unassessed. Nothing is scored until you log relevant data. All targets can be edited in Settings.</p></div><div class="field full"><button class="btn primary" type="submit">${icon('sparkles')} Enter your universe</button></div></form>`;
 return `<div class="auth-screen"><div class="auth-art"><div class="brand"><div class="brand-symbol" role="img" aria-label="Mortal skull emblem"></div><div><div class="brand-name">Mortal<span>.</span></div><div class="brand-sub">Your life. Your RPG.</div></div></div><div><div class="eyebrow">THE START OF YOUR STORY</div><h1>A life built around <span>your priorities.</span></h1><p>A personalized adventure, not another list of things you should be doing.</p></div><div class="auth-note">Your information is yours. Every optional area can stay private.</div></div><div class="auth-panel"><div class="auth-box" style="max-width:490px"><div class="eyebrow">STEP ${onboardStep+1} OF 3</div><h2>${steps[onboardStep]}</h2><p>Set your own pace. You can change these choices later.</p><div class="steps">${steps.map((_,i)=>`<div class="${i<=onboardStep?'active':''}"></div>`).join('')}</div>${content}<p style="font-size:10px;margin-top:26px">Personalized Life Scores are progress indicators, not medical or moral judgments.</p></div></div></div>`;
}
function auth(){if(globalThis.location?.protocol==='file:')return `<div class="auth-screen"><div class="auth-art"><div class="brand"><div class="brand-symbol" role="img" aria-label="Mortal skull emblem"></div><div><div class="brand-name">Mortal<span>.</span></div><div class="brand-sub">Your life. Your RPG.</div></div></div><div><div class="eyebrow">YOUR LIFE. YOUR LEGEND.</div><h1>Level up your life.<br><span>On your terms.</span></h1><p>Explore a fictional character with real calculations, RPG progression and adjustable personal targets.</p></div><div class="auth-note">Standalone demo · No account or server required</div></div><div class="auth-panel"><div class="auth-box"><div class="eyebrow">INTERACTIVE PREVIEW</div><h2>Meet Alex.</h2><p>Open the offline demonstration. Edit measurements, create quests, change weights and explore all screens. Changes are saved in your browser where available.</p><button class="btn primary" style="width:100%;margin-top:25px;padding:16px" data-action="demo">${icon('zap')} Enter the interactive demo ${icon('arrow-right')}</button><p style="margin-top:20px">To create a private account with SQLite persistence, run the server version included in the full project.</p></div></div></div>`;const login=authPage==='login',signup=authPage==='signup';return `<div class="auth-screen"><div class="auth-art"><div class="brand" style="margin:0"><div class="brand-symbol" role="img" aria-label="Mortal skull emblem"></div><div><div class="brand-name">Mortal<span>.</span></div><div class="brand-sub">Your life. Your RPG.</div></div></div><div><div class="eyebrow">YOUR LIFE. YOUR LEGEND.</div><h1>Level up your life.<br><span>On your terms.</span></h1><p>Turn real milestones into quests, meaningful action into experience, and personal progress into a story worth remembering.</p><div class="chips" style="margin-top:29px"><span class="chip">${icon('shield')} Private by design</span><span class="chip">${icon('chart')} Measurable growth</span><span class="chip">${icon('zap')} Real-world XP</span></div></div><div class="auth-note">Mortal · Progress is personal, not a competition.</div></div><div class="auth-panel"><div class="auth-box">${login||signup?`<div class="eyebrow">${signup?'CREATE YOUR CHARACTER':'WELCOME BACK'}</div><h2>${signup?'Begin your adventure':'Continue your story'}</h2><p>${signup?'Create a private account. Your personal data is kept on your own Mortal server.':'Your character and progress are right where you left them.'}</p><form class="auth-form" id="${signup?'signup':'login'}-form">${signup?'<div class="field"><label>Preferred name</label><input class="input" name="name" required maxlength="60" placeholder="How should we call you?"></div>':''}<div class="field"><label>Email address</label><input class="input" name="email" required type="email" autocomplete="email" placeholder="you@example.com"></div><div class="field"><label>Password</label><input class="input" name="password" required type="password" ${signup?'minlength="10" autocomplete="new-password"':'autocomplete="current-password"'} placeholder="${signup?'At least 10 characters':'Your password'}"></div><button class="btn primary" type="submit">${signup?'Create account':'Sign in'} ${icon('arrow-right')}</button></form><p style="margin-top:24px">${signup?'Already have an account?':'New here?'} <button class="auth-toggle" data-auth="${signup?'login':'signup'}">${signup?'Sign in':'Create an account'}</button></p>`:`<div class="eyebrow">PLAYER ONE, READY?</div><h2>Begin your story.</h2><p>Your personal progress universe is one step away. Explore the fictional demo or create a private account to begin with your real data.</p><div style="display:grid;gap:11px;margin-top:30px"><button class="btn primary" style="padding:14px" data-auth="signup">${icon('sparkles')} Create your character ${icon('arrow-right')}</button><button class="btn ghost" style="padding:14px" data-action="demo">${icon('zap')} Explore Alex's demo</button></div><div class="auth-divide">OR</div><button class="btn ghost" style="width:100%" data-auth="login">I already have an account</button><p style="font-size:10px;margin-top:22px">Demo data is fictional and stored separately in this browser.</p>`}${login||signup?`<button class="auth-toggle" style="margin-top:12px" data-auth="welcome">← Back to welcome</button>`:''}</div></div></div>`;}
function render(){if(!s){app.innerHTML=auth();return;}if(!s.profile.onboarded){app.innerHTML=onboarding();return;}const pages={dashboard,categories,category:categoryDetail,quests:questsPage,checkin,goals:goalsPage,character:characterPage,analytics:analyticsPage,achievements:achievementsPage,settings:settingsPage};app.innerHTML=(pages[page]||dashboard)()+modalMarkup();document.title=`Mortal · ${page[0].toUpperCase()+page.slice(1)}`;}
function recordMeasurement({metricId,value,date,note,id}){
 const v=Number(value),d=String(date||today());if(!Number.isFinite(v)||v<0||v>1e12)throw Error('Enter a valid non-negative measurement.');
 if(!s.metrics.some(m=>m.id===metricId&&m.active!==false))throw Error('Select an active metric.');
 if(!/^\d{4}-\d{2}-\d{2}$/.test(d)||d>today())throw Error('Choose a valid date not in the future.');
 let created=false;
 change(st=>{if(id){const old=st.observations.find(o=>o.id===id);if(!old)throw Error('Measurement no longer exists.');Object.assign(old,{metricId,value:v,date:new Date(d+'T12:00:00').toISOString(),note:String(note||'').slice(0,300)});}else{
 const newObs={id:uid(),metricId,value:v,date:new Date(d+'T12:00:00').toISOString(),note:String(note||'').slice(0,300)};
 // A short duplicate guard prevents accidental double submissions of identical values.
 if(st.observations.some(o=>o.metricId===metricId&&o.value===v&&isoDay(o.date)===d&&o.note===newObs.note&&Date.now()-new Date(o.createdAt||0).getTime()<10000))throw Error('This measurement was just submitted.');
 newObs.createdAt=new Date().toISOString();st.observations.push(newObs);grantXP(st,`log:${metricId}:${d}`,5,'Daily activity recorded',st.metrics.find(m=>m.id===metricId)?.categoryId);created=true;
 }},created?'Activity saved · score updated':'Measurement updated');
}
document.addEventListener('click',async e=>{
 try{
  const navEl=e.target.closest('[data-nav]');if(navEl){const p=navEl.dataset.nav;switchPage(p,navEl.dataset.category||undefined);return;}
  const catEl=e.target.closest('[data-category]');if(catEl&&!catEl.hasAttribute('data-category-toggle')){switchPage('category',catEl.dataset.category);return;}
  const authEl=e.target.closest('[data-auth]');if(authEl){authPage=authEl.dataset.auth;render();return;}
  const filterEl=e.target.closest('[data-quest-filter]');if(filterEl){questFilter=filterEl.dataset.questFilter;render();return;}
  const questEl=e.target.closest('[data-complete-quest]');if(questEl){const id=questEl.dataset.completeQuest;const q=s.quests.find(x=>x.id===id);if(!q||q.doneAt)return;change(st=>{const quest=st.quests.find(x=>x.id===id);quest.doneAt=new Date().toISOString();grantXP(st,`quest:${id}`,quest.reward,`Completed: ${quest.name}`,quest.categoryId);},`Quest completed! +${q.reward} XP`);return;}
  const obsEl=e.target.closest('[data-edit-observation]');if(obsEl){modal={type:'observation',id:obsEl.dataset.editObservation};render();return;}
  const delObs=e.target.closest('[data-delete-observation]');if(delObs){if(!confirm('Delete this measurement and recalculate affected scores?'))return;change(st=>{st.observations=st.observations.filter(o=>o.id!==delObs.dataset.deleteObservation)},'Measurement removed · scores recalculated');return;}
  const delQuest=e.target.closest('[data-delete-quest]');if(delQuest){const q=s.quests.find(x=>x.id===delQuest.dataset.deleteQuest);if(q?.doneAt){toast('Completed quests remain in your achievement history.');return;}if(!confirm('Delete this quest?'))return;change(st=>st.quests=st.quests.filter(x=>x.id!==q.id),'Quest removed');return;}
  const editGoal=e.target.closest('[data-edit-goal]');if(editGoal){modal={type:'goal',id:editGoal.dataset.editGoal};render();return;}
  const delGoal=e.target.closest('[data-delete-goal]');if(delGoal){if(!confirm('Delete this personal goal?'))return;change(st=>st.goals=st.goals.filter(x=>x.id!==delGoal.dataset.deleteGoal),'Goal deleted');return;}
  const editMetric=e.target.closest('[data-edit-metric]');if(editMetric){modal={type:'metric',id:editMetric.dataset.editMetric};render();return;}
  const logMetric=e.target.closest('[data-log-metric]');if(logMetric){modal={type:'observation',metricId:logMetric.dataset.logMetric};render();return;}
  const action=e.target.closest('[data-action]')?.dataset.action;
  switch(action){
   case 'demo':{let saved=null;try{saved=localStorage.getItem('mortal_demo_v1')||localStorage.getItem('ava_demo_v1');s=saved?JSON.parse(saved):makeDemoState();}catch{s=makeDemoState();}mode='demo';page='dashboard';modal=null;render();break;}
   case 'leave-demo':s=null;mode=null;authPage='welcome';render();break;
   case 'log-open':modal={type:'observation'};render();break;
   case 'quest-open':modal={type:'quest'};render();break;
   case 'goal-open':modal={type:'goal'};render();break;
   case 'custom-category':modal={type:'category'};render();break;
   case 'custom-metric':modal={type:'metric'};render();break;
   case 'close-modal':modal=null;render();break;
   case 'onboard-back':onboardStep=Math.max(0,onboardStep-1);render();break;
   case 'export':{const blob=new Blob([JSON.stringify(s,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`mortal-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Personal data exported');break;}
   case 'import':$('#import-file')?.click();break;
   case 'logout':{if(mode==='account'){await api('/api/logout','POST',{});}s=null;mode=null;authPage='welcome';render();break;}
   case 'clear-data':{if(!confirm('Permanently clear observations, quests, goals, XP and history? Your profile and scoring rules will stay.'))return;change(st=>{st.observations=[];st.quests=[];st.goals=[];st.achievements=[];st.xpTransactions=[];st.scoreSnapshots=[];},'All activity data cleared');break;}
   case 'delete-account':modal={type:'delete-account'};render();break;
  }
  if(e.target.id==='modal-backdrop'){modal=null;render();}
 }catch(err){toast(err.message);}
});
document.addEventListener('input',e=>{const el=e.target.closest('[data-category-weight]');if(el){const span=document.getElementById('weight-'+el.dataset.categoryWeight);if(span)span.textContent='×'+Number(el.value);}});
document.addEventListener('change',async e=>{
 try{
  const el=e.target;
  if(el.matches('[data-category-toggle]')){const id=el.dataset.categoryToggle;change(st=>{if(el.checked&&!st.activeCategories.includes(id))st.activeCategories.push(id);if(!el.checked)st.activeCategories=st.activeCategories.filter(x=>x!==id);bumpRules(st,`${el.checked?'Enabled':'Disabled'} ${category(id).name}`);},'Category selection updated');}
  if(el.matches('[data-category-weight]')){const id=el.dataset.categoryWeight,v=Number(el.value);change(st=>{st.categoryWeights[id]=v;bumpRules(st,`Adjusted ${category(id).name} importance to ${v}`);},'Category weights updated');}
  if(el.id==='import-file'){
   const file=el.files?.[0];if(!file)return;const parsed=JSON.parse(await file.text());if(!parsed.profile||!Array.isArray(parsed.metrics)||!Array.isArray(parsed.observations)||!Array.isArray(parsed.activeCategories)||!Array.isArray(parsed.quests)||!Array.isArray(parsed.goals)||!Array.isArray(parsed.xpTransactions))throw Error('Invalid Mortal backup.');if(!confirm('Replace your current Mortal data with the imported backup?'))return;
   if(mode==='account')parsed.demo=false;else parsed.demo=true;s=parsed;recordSnapshot(s);save();page='dashboard';render();toast('Your Mortal backup is restored');
  }
 }catch(err){toast(err.message);render();}
});
document.addEventListener('submit',async e=>{
 const form=e.target;if(!(form instanceof HTMLFormElement))return;e.preventDefault();const f=Object.fromEntries(new FormData(form).entries());try{
  if(form.id==='signup-form'){const out=await api('/api/signup','POST',f);s=out.state;email=out.email;revision=out.revision;mode='account';onboardStep=0;page='dashboard';render();toast('Account created. Build your character!');return;}
  if(form.id==='login-form'){const out=await api('/api/login','POST',f);const loaded=await api('/api/state');s=loaded.state;revision=loaded.revision;email=out.email;mode='account';onboardStep=0;page='dashboard';render();toast('Welcome back!');return;}
  if(form.id==='onboard-step-0'){s.profile={...s.profile,name:String(f.name).trim(),avatar:String(f.avatar||'A').slice(0,2),role:String(f.role||''),currency:String(f.currency||'USD').slice(0,5),intensity:String(f.intensity)};onboardStep=1;save();render();return;}
  if(form.id==='onboard-step-1'){const selected=new FormData(form).getAll('category');if(!selected.length)throw Error('Choose at least one category to track.');s.activeCategories=selected;onboardStep=2;save();render();return;}
  if(form.id==='onboard-step-2'){s.profile.priorities=String(f.priorities||'').split(',').map(x=>x.trim()).filter(Boolean).slice(0,3);s.profile.onboarded=true;recordSnapshot(s);save();page='dashboard';render();toast('Your story begins here');return;}
  if(form.id==='profile-form'){change(st=>{st.profile.name=String(f.name||'').trim().slice(0,60);st.profile.avatar=String(f.avatar||'A').slice(0,2);st.profile.role=String(f.role||'').slice(0,80);st.profile.currency=String(f.currency||'USD').slice(0,5);st.profile.intensity=String(f.intensity||'balanced');},'Profile updated');return;}
  if(form.id==='dimension-form'){const dims={progress:Number(f.progress)/100,consistency:Number(f.consistency)/100,growth:Number(f.growth)/100};if(Object.values(dims).some(x=>!Number.isFinite(x)||x<0||x>1)||Object.values(dims).every(x=>x===0))throw Error('Weights must be non-negative and at least one above zero.');change(st=>{st.dimensions=dims;bumpRules(st,'Adjusted progress / consistency / growth blending');},'Score formula updated and versioned');return;}
  if(form.id==='checkin-form'||form.id==='observation-form'){
   recordMeasurement({id:f.id||null,metricId:f.metricId,value:f.value,date:f.date,note:f.note});modal=null;render();return;
  }
  if(form.id==='quest-form'){
   const name=String(f.name||'').trim(),reward=Number(f.reward);if(!name||!Number.isFinite(reward)||reward<5||reward>1000)throw Error('Enter a valid quest and XP reward.');
   change(st=>st.quests.push({id:uid(),name,description:String(f.description||'').slice(0,400),categoryId:f.categoryId,type:f.type,difficulty:f.difficulty,due:f.due||null,reward,doneAt:null,createdAt:new Date().toISOString()}),'Quest added to your board');modal=null;render();return;
  }
  if(form.id==='goal-form'){
   const progress=Number(f.progress);if(!Number.isFinite(progress)||progress<0||progress>100)throw Error('Progress must be between 0 and 100.');
   change(st=>{if(f.id){const g=st.goals.find(x=>x.id===f.id);if(!g)throw Error('Goal not found.');Object.assign(g,{name:String(f.name).trim(),categoryId:f.categoryId,targetDate:f.targetDate||null,progress});}else st.goals.push({id:uid(),name:String(f.name).trim(),categoryId:f.categoryId,targetDate:f.targetDate||null,progress});},'Goal saved');modal=null;render();return;
  }
  if(form.id==='category-form'){
   const name=String(f.name||'').trim(),color=String(f.color||'#c3a6ff');if(!name)throw Error('Enter a category name.');
   change(st=>{const id=`custom-${uid()}`;st.customCategories ||= [];st.customCategories.push({id,name,desc:String(f.desc||'').slice(0,110),color:/^#[0-9a-f]{6}$/i.test(color)?color:'#c3a6ff',icon:'sparkles'});st.activeCategories.push(id);st.categoryWeights[id]=Number(f.weight)||1;bumpRules(st,`Added category: ${name}`);},'Custom category created. Add a metric to assess it.');modal=null;render();return;
  }
  if(form.id==='metric-form'){
   const n=['target','baseline','windowDays','weight','min','max'];for(const field of n)if(f[field]!==''&&!Number.isFinite(Number(f[field])))throw Error(`Invalid ${field}.`);
   if(Number(f.windowDays)<1||Number(f.windowDays)>3650||Number(f.weight)<0||Number(f.weight)>100)throw Error('Check the evaluation window and metric weight.');
   if(f.method==='range'&&Number(f.min)>Number(f.max))throw Error('The minimum range value cannot exceed the maximum.');
   const m={id:f.id||`custommetric-${uid()}`,name:String(f.name).trim().slice(0,70),categoryId:f.categoryId,unit:String(f.unit).trim().slice(0,35),method:f.method,dimension:f.dimension,target:Number(f.target),baseline:Number(f.baseline),min:Number(f.min||0),max:Number(f.max||100),tolerance:10,windowDays:Number(f.windowDays),weight:Number(f.weight),aggregate:f.aggregate,active:f.active==='yes',exemptDates:String(f.exemptDates||'').split(',').map(v=>v.trim()).filter(v=>/^\d{4}-\d{2}-\d{2}$/.test(v)),pausedUntil:f.pausedUntil||null,source:'manual'};
   if(!m.name||!m.unit)throw Error('Metric name and unit are required.');
   change(st=>{const i=st.metrics.findIndex(x=>x.id===m.id);if(i>=0)st.metrics[i]={...st.metrics[i],...m};else st.metrics.push(m);bumpRules(st,`Updated metric: ${m.name}`);},'Scoring rule saved and versioned');modal=null;render();return;
  }
  if(form.id==='delete-account-form'){await api('/api/account','DELETE',{password:f.password});s=null;mode=null;modal=null;authPage='welcome';render();toast('Account and personal data deleted');return;}
 }catch(err){toast(err.message);}
});
async function initialize(){try{const ses=await api('/api/session');if(ses.authenticated){const data=await api('/api/state');s=data.state;revision=data.revision;email=ses.email;mode='account';}}catch(err){console.warn('Connection issue:',err);toast('Unable to connect to Mortal server.');}render();if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});}
initialize();
